import org.apache.commons.math3.distribution.PoissonDistribution;
import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
      double lambdaHistorico = 2.0;
      PoissonDistribution dist = new PoissonDistribution(lambdaHistorico);

      int[] prediccion10Dias = dist.sample(10);
      System.out.println(Arrays.toString(prediccion10Dias));
  }
}
